package in.tucor.api.auth;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.context.annotation.Import; import org.springframework.test.web.servlet.MockMvc; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.when; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
@WebMvcTest(AuthController.class) @Import(in.tucor.api.config.SecurityConfig.class) class AuthControllerTest {@Autowired MockMvc mvc;@MockBean AuthService service;@MockBean JwtService jwt; @MockBean in.tucor.api.auth.RegistrationDocumentRepository registrationDocumentRepository;@Test void loginIsPublic() throws Exception {when(service.login(any())).thenReturn(new AuthDtos.Tokens("a","r","Bearer",900,Role.BUYER,"buyer@test.com"));mvc.perform(post("/api/auth/login").contentType("application/json").content("{\"email\":\"buyer@test.com\",\"password\":\"Password@123\"}")).andExpect(status().isOk());}}